 r[str(i)]={**o,'outcome':out,'credit':0,'formal_endpoint':None,'review_depth':'literal plus targeted primary statement/context; sustained mechanisms' if out=='sustained_parked' else 'literal plus targeted primary statement/context; depth and gaps specified in note','assessment':note,'source_receipt':str(p.relative_to(D))+'.receipt.json','source_body_sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'history_check':'Exact IDs and literal titles searched in bounded campaign prose/results/reviews/ledgers; history-matches.txt. Assignment/metadata hits are not substantive review.','prior_art_limits':'Dated primary HTTP receipts and grouped source-ID/title web searches retained. No exhaustive citing literature, publisher-version or registry proof-body audit. No novelty clearance claimed.','remaining_lean':'No qualifying ordinary endpoint; no Lean packet/rebuild/leanchecker/axiom audit claimed.'}
